{"description":"Decode trunc.db cells into records","cmd":"python3 << 'EOF'
import struct, json

with open('/app/trunc.db','rb') as f:
    page = f.read()

ptype = page[0]
ncells = int.from_bytes(page[3:5], 'big')
content_start = int.from_bytes(page[5:7], 'big')
print(f'page type=0x{ptype:02x}, ncells={ncells}, content_start={content_start}')

def read_varint(buf, pos):
    # sqlite varint up to 9 bytes
    result = 0
    for i in range(8):
        b = buf[pos]; pos += 1
        result = (result << 7) | (b & 0x7f)
        if b < 0x80:
            return result, pos
    b = buf[pos]; pos += 1
    result = (result << 8) | b
    return result, pos

def decode_record(payload):
    hdr_size, pos = read_varint(payload, 0)
    serials = []
    while pos < hdr_size:
        t, pos = read_varint(payload, pos)
        serials.append(t)
    data_pos = hdr_size
    cols = []
    for t in serials:
        if t == 0:
            size = 0; val = None
        elif t == 1:
            size = 1
        elif t == 2:
            size = 2
        elif t == 3:
            size = 3
        elif t == 4:
            size = 4
        elif t == 5:
            size = 6
        elif t == 6:
            size = 8
        elif t == 7:
            size = 8
        elif t == 8:
            size = 0; val = 0
        elif t == 9:
            size = 0; val = 1
        elif t == 10:
            size = 0; val = 0
        elif t == 11:
            size = 0; val = 1
        elif t >= 12 and t % 2 == 0:
            size = (t - 12) // 2
        else:
            size = (t - 13) // 2
        raw = payload[data_pos:data_pos+size]
        data_pos += size
        if t == 0:
            val = None
        elif t in (8,9,10,11):
            pass
        elif t == 1:
            val = int.from_bytes(raw, 'big', signed=True)
        elif t in (2,3):
            val = int.from_bytes(raw, 'big', signed=True)
        elif t == 4:
            val = int.from_bytes(raw, 'big', signed=True)
        elif t in (5,6):
            val = int.from_bytes(raw, 'big', signed=True)
        elif t == 7:
            val = struct.unpack('>d', raw)[0]
        elif t % 2 == 1:  # blob/text odd
            val = raw.decode('utf-8', errors='replace')
        else:  # text even
            val = raw.decode('utf-8', errors='replace')
        cols.append((t, size, val))
    return cols

rows = []
for i in range(ncells):
    ptr = int.from_bytes(page[8+2*i:10+2*i], 'big')
    buf = page[ptr:]
    # table leaf cell: payload len varint, rowid varint, payload
    plen, pos = read_varint(buf, 0)
    rowid, pos = read_varint(buf, pos)
    payload = buf[pos:pos+plen]
    cols = decode_record(payload)
    # find word and value columns
    word = None; value = None
    for t, size, val in cols:
        if isinstance(val, str) and val.startswith('testword'):
            word = val
        elif isinstance(val, (int, float)):
            value = val
    rows.append({'rowid': rowid, 'word': word, 'value': value, 'cols': cols})
    print(f'cell[{i}] ptr={ptr} rowid={rowid} payload_len={plen}')
    print('   record cols:', [(t, size, val) for t,size,val in cols])

# The expected output shape
out = [{'word': r['word'], 'value': r['value']} for r in rows]
print(json.dumps(out, indent=2))
EOF"}

